fun maxSumSubarray(nums: IntArray, k: Int): Int {
    var windowSum = 0
    for (i in 0 until k) windowSum += nums[i]

    var best = windowSum
    for (end in k until nums.size) {
        // One element enters on the right, one leaves on the left.
        windowSum += nums[end] - nums[end - k]
        best = maxOf(best, windowSum)
    }
    return best
}

fun lengthOfLongestSubstring(s: String): Int {
    val lastSeen = HashMap<Char, Int>()
    var start = 0
    var best = 0

    for (end in s.indices) {
        val c = s[end]
        val seen = lastSeen[c]
        // Only jump if the duplicate is inside the current window.
        if (seen != null && seen >= start) start = seen + 1
        lastSeen[c] = end
        best = maxOf(best, end - start + 1)
    }
    return best
}

fun minWindow(s: String, t: String): String {
    if (t.isEmpty() || s.length < t.length) return ""

    val need = HashMap<Char, Int>()
    for (c in t) need[c] = (need[c] ?: 0) + 1

    var missing = t.length
    var start = 0
    var bestStart = 0
    var bestLen = Int.MAX_VALUE

    for (end in s.indices) {
        val c = s[end]
        val count = need[c] ?: 0
        if (count > 0) missing--          // covered a real requirement
        need[c] = count - 1               // surplus goes negative

        while (missing == 0) {
            if (end - start + 1 < bestLen) {
                bestLen = end - start + 1
                bestStart = start
            }
            val left = s[start]
            val restored = (need[left] ?: 0) + 1
            need[left] = restored
            if (restored > 0) missing++    // window just broke
            start++
        }
    }

    return if (bestLen == Int.MAX_VALUE) "" else s.substring(bestStart, bestStart + bestLen)
}

fun twoSumSorted(nums: IntArray, target: Int): IntArray {
    var lo = 0
    var hi = nums.size - 1

    while (lo < hi) {
        val sum = nums[lo] + nums[hi]
        when {
            sum == target -> return intArrayOf(lo, hi)
            sum < target -> lo++     // need a bigger sum
            else -> hi--             // need a smaller sum
        }
    }
    return intArrayOf(-1, -1)
}

fun threeSum(nums: IntArray): List<List<Int>> {
    nums.sort()
    val out = mutableListOf<List<Int>>()

    for (i in nums.indices) {
        if (nums[i] > 0) break                          // sorted: no zero-sum left
        if (i > 0 && nums[i] == nums[i - 1]) continue   // duplicate anchor

        var lo = i + 1
        var hi = nums.size - 1
        while (lo < hi) {
            val sum = nums[i] + nums[lo] + nums[hi]
            when {
                sum < 0 -> lo++
                sum > 0 -> hi--
                else -> {
                    out += listOf(nums[i], nums[lo], nums[hi])
                    while (lo < hi && nums[lo] == nums[lo + 1]) lo++
                    while (lo < hi && nums[hi] == nums[hi - 1]) hi--
                    lo++
                    hi--
                }
            }
        }
    }
    return out
}

fun trap(height: IntArray): Int {
    var lo = 0
    var hi = height.size - 1
    var leftMax = 0
    var rightMax = 0
    var water = 0

    while (lo < hi) {
        if (height[lo] < height[hi]) {
            // Left is the shorter wall, so leftMax alone decides this column.
            leftMax = maxOf(leftMax, height[lo])
            water += leftMax - height[lo]
            lo++
        } else {
            rightMax = maxOf(rightMax, height[hi])
            water += rightMax - height[hi]
            hi--
        }
    }
    return water
}

class Node(val value: Int) { var next: Node? = null }

fun hasCycle(head: Node?): Boolean {
    var slow = head
    var fast = head

    while (fast?.next != null) {
        slow = slow?.next
        fast = fast.next?.next
        if (slow === fast) return true   // identity, not equality
    }
    return false
}

fun detectCycleStart(head: Node?): Node? {
    var slow = head
    var fast = head

    while (fast?.next != null) {
        slow = slow?.next
        fast = fast.next?.next
        if (slow === fast) {
            // Phase 2: equal-speed walk from head and meeting point.
            var entry = head
            while (entry !== slow) {
                entry = entry?.next
                slow = slow?.next
            }
            return entry
        }
    }
    return null
}

fun findDuplicate(nums: IntArray): Int {
    // Phase 1: find a meeting point inside the cycle.
    var slow = nums[0]
    var fast = nums[0]
    do {
        slow = nums[slow]
        fast = nums[nums[fast]]
    } while (slow != fast)

    // Phase 2: walk from the start to the cycle entry.
    slow = nums[0]
    while (slow != fast) {
        slow = nums[slow]
        fast = nums[fast]
    }
    return slow
}

fun merge(intervals: Array<IntArray>): List<IntArray> {
    if (intervals.isEmpty()) return emptyList()
    intervals.sortBy { it[0] }

    // Copy the first so the input array is never mutated through aliasing.
    val out = mutableListOf(intArrayOf(intervals[0][0], intervals[0][1]))
    for (i in 1 until intervals.size) {
        val last = out.last()
        val cur = intervals[i]
        if (cur[0] <= last[1]) {
            last[1] = maxOf(last[1], cur[1])   // overlap: extend
        } else {
            out += intArrayOf(cur[0], cur[1])  // gap: start fresh
        }
    }
    return out
}

fun insert(intervals: Array<IntArray>, newInterval: IntArray): List<IntArray> {
    val out = mutableListOf<IntArray>()
    val n = intervals.size
    var i = 0

    // 1. Everything strictly before the new interval.
    while (i < n && intervals[i][1] < newInterval[0]) out += intervals[i++]

    // 2. Absorb the overlap run.
    var start = newInterval[0]
    var end = newInterval[1]
    while (i < n && intervals[i][0] <= end) {
        start = minOf(start, intervals[i][0])
        end = maxOf(end, intervals[i][1])
        i++
    }
    out += intArrayOf(start, end)

    // 3. Everything strictly after.
    while (i < n) out += intervals[i++]
    return out
}

fun minMeetingRooms(intervals: Array<IntArray>): Int {
    if (intervals.isEmpty()) return 0

    val starts = intervals.map { it[0] }.sorted()
    val ends = intervals.map { it[1] }.sorted()

    var rooms = 0
    var peak = 0
    var e = 0

    for (s in starts) {
        // Free every room whose meeting has already finished.
        while (e < ends.size && ends[e] <= s) {
            rooms--
            e++
        }
        rooms++
        peak = maxOf(peak, rooms)
    }
    return peak
}

import java.util.PriorityQueue

fun findKthLargest(nums: IntArray, k: Int): Int {
    val heap = PriorityQueue<Int>()   // natural order = min-heap

    for (n in nums) {
        heap.add(n)
        if (heap.size > k) heap.poll()   // drop the weakest candidate
    }
    return heap.peek()
}

import java.util.PriorityQueue

fun topKFrequent(nums: IntArray, k: Int): List<Int> {
    val counts = HashMap<Int, Int>()
    for (n in nums) counts[n] = (counts[n] ?: 0) + 1

    // Min-heap on frequency: the root is the weakest of the current top k.
    val heap = PriorityQueue<Map.Entry<Int, Int>>(compareBy { it.value })
    for (entry in counts.entries) {
        heap.add(entry)
        if (heap.size > k) heap.poll()
    }
    return heap.map { it.key }
}

import java.util.PriorityQueue

fun mergeKLists(lists: List<Node?>): Node? {
    val heap = PriorityQueue<Node>(compareBy { it.value })
    for (head in lists) if (head != null) heap.add(head)

    val dummy = Node(0)
    var tail = dummy
    while (heap.isNotEmpty()) {
        val node = heap.poll()
        tail.next = node
        tail = node
        node.next?.let { heap.add(it) }   // refill from the same list
    }
    tail.next = null                      // cut any stale link
    return dummy.next
}

fun search(nums: IntArray, target: Int): Int {
    var lo = 0
    var hi = nums.size - 1

    while (lo <= hi) {
        val mid = lo + (hi - lo) / 2   // overflow-safe midpoint
        when {
            nums[mid] == target -> return mid
            nums[mid] < target -> lo = mid + 1
            else -> hi = mid - 1
        }
    }
    return -1
}

fun searchRotated(nums: IntArray, target: Int): Int {
    var lo = 0
    var hi = nums.size - 1

    while (lo <= hi) {
        val mid = lo + (hi - lo) / 2
        if (nums[mid] == target) return mid

        if (nums[lo] <= nums[mid]) {
            // Left half is sorted — can we range-check the target into it?
            if (target >= nums[lo] && target < nums[mid]) hi = mid - 1 else lo = mid + 1
        } else {
            // Right half is sorted.
            if (target > nums[mid] && target <= nums[hi]) lo = mid + 1 else hi = mid - 1
        }
    }
    return -1
}

fun minEatingSpeed(piles: IntArray, h: Int): Int {
    var lo = 1
    var hi = piles.max()

    while (lo < hi) {
        val mid = lo + (hi - lo) / 2
        // Ceiling division without floating point; Long guards against overflow.
        val hours = piles.sumOf { ((it + mid - 1) / mid).toLong() }
        if (hours <= h) hi = mid else lo = mid + 1
    }
    return lo
}

class NumArray(nums: IntArray) {
    private val prefix = IntArray(nums.size + 1)

    init {
        // prefix[i + 1] holds the sum of the first i + 1 elements.
        for (i in nums.indices) prefix[i + 1] = prefix[i] + nums[i]
    }

    fun sumRange(left: Int, right: Int): Int = prefix[right + 1] - prefix[left]
}

fun subarraySum(nums: IntArray, k: Int): Int {
    val counts = HashMap<Int, Int>()
    counts[0] = 1          // empty prefix, so subarrays from index 0 count

    var running = 0
    var total = 0
    for (n in nums) {
        running += n
        total += counts[running - k] ?: 0
        counts[running] = (counts[running] ?: 0) + 1
    }
    return total
}

fun findMaxLength(nums: IntArray): Int {
    val firstIndex = HashMap<Int, Int>()
    firstIndex[0] = -1     // balance 0 "occurred" before the array

    var balance = 0
    var best = 0
    for (i in nums.indices) {
        balance += if (nums[i] == 1) 1 else -1
        val seen = firstIndex[balance]
        if (seen != null) {
            best = maxOf(best, i - seen)
        } else {
            firstIndex[balance] = i   // keep the earliest only
        }
    }
    return best
}

fun twoSum(nums: IntArray, target: Int): IntArray {
    val seen = HashMap<Int, Int>()   // value -> index

    for (i in nums.indices) {
        val need = target - nums[i]
        seen[need]?.let { return intArrayOf(it, i) }
        seen[nums[i]] = i            // insert after the check
    }
    return intArrayOf(-1, -1)
}

fun groupAnagrams(words: Array<String>): List<List<String>> {
    val groups = HashMap<String, MutableList<String>>()

    for (w in words) {
        val counts = IntArray(26)
        for (c in w) counts[c - 'a']++
        val key = counts.joinToString(",")   // O(L) fingerprint
        groups.getOrPut(key) { mutableListOf() }.add(w)
    }
    return groups.values.toList()
}

fun longestConsecutive(nums: IntArray): Int {
    val set = nums.toHashSet()
    var best = 0

    for (n in set) {
        if (set.contains(n - 1)) continue   // not the start of a run

        var length = 1
        while (set.contains(n + length)) length++
        best = maxOf(best, length)
    }
    return best
}

fun isValid(s: String): Boolean {
    val stack = ArrayDeque<Char>()
    val pairs = mapOf(')' to '(', ']' to '[', '}' to '{')

    for (c in s) {
        val expectedOpener = pairs[c]
        if (expectedOpener == null) {
            stack.addLast(c)                                  // an opener
        } else if (stack.removeLastOrNull() != expectedOpener) {
            return false                                      // mismatch or nothing to close
        }
    }
    return stack.isEmpty()
}

fun dailyTemperatures(temps: IntArray): IntArray {
    val answer = IntArray(temps.size)
    val stack = ArrayDeque<Int>()   // indices, temperatures decreasing bottom → top

    for (i in temps.indices) {
        while (stack.isNotEmpty() && temps[i] > temps[stack.last()]) {
            val j = stack.removeLast()
            answer[j] = i - j       // day i resolves day j
        }
        stack.addLast(i)
    }
    return answer                   // unresolved days stay 0
}

fun largestRectangleArea(heights: IntArray): Int {
    val stack = ArrayDeque<Int>()   // indices, heights increasing
    var best = 0

    // The extra i == size step uses height 0 to drain the stack.
    for (i in 0..heights.size) {
        val h = if (i == heights.size) 0 else heights[i]

        while (stack.isNotEmpty() && heights[stack.last()] >= h) {
            val height = heights[stack.removeLast()]
            val left = if (stack.isEmpty()) -1 else stack.last()
            best = maxOf(best, height * (i - left - 1))
        }
        stack.addLast(i)
    }
    return best
}

class TreeNode(val value: Int) {
    var left: TreeNode? = null
    var right: TreeNode? = null
}

fun maxDepth(root: TreeNode?): Int =
    if (root == null) 0
    else 1 + maxOf(maxDepth(root.left), maxDepth(root.right))

fun levelOrder(root: TreeNode?): List<List<Int>> {
    if (root == null) return emptyList()

    val out = mutableListOf<List<Int>>()
    val queue = ArrayDeque<TreeNode>()
    queue.addLast(root)

    while (queue.isNotEmpty()) {
        val levelSize = queue.size      // snapshot before draining
        val level = ArrayList<Int>(levelSize)

        repeat(levelSize) {
            val node = queue.removeFirst()
            level += node.value
            node.left?.let { queue.addLast(it) }
            node.right?.let { queue.addLast(it) }
        }
        out += level
    }
    return out
}

fun numIslands(grid: Array<CharArray>): Int {
    if (grid.isEmpty()) return 0
    var count = 0

    fun sink(r: Int, c: Int) {
        if (r !in grid.indices || c !in grid[0].indices || grid[r][c] != '1') return
        grid[r][c] = '0'          // mark visited in place
        sink(r + 1, c)
        sink(r - 1, c)
        sink(r, c + 1)
        sink(r, c - 1)
    }

    for (r in grid.indices) {
        for (c in grid[0].indices) {
            if (grid[r][c] == '1') {
                count++
                sink(r, c)
            }
        }
    }
    return count
}

fun climbStairs(n: Int): Int {
    var prev = 1   // ways(i - 2)
    var cur = 1    // ways(i - 1)

    for (i in 2..n) {
        val next = prev + cur
        prev = cur
        cur = next
    }
    return cur
}

fun maxSubArray(nums: IntArray): Int {
    var current = nums[0]   // best sum of a subarray ending at i
    var best = nums[0]

    for (i in 1 until nums.size) {
        current = maxOf(nums[i], current + nums[i])   // restart or extend
        best = maxOf(best, current)
    }
    return best
}

fun rob(nums: IntArray): Int {
    var skip = 0   // best through house i - 2
    var take = 0   // best through house i - 1

    for (n in nums) {
        val next = maxOf(take, skip + n)   // skip this house, or rob it
        skip = take
        take = next
    }
    return take
}

fun coinChange(coins: IntArray, amount: Int): Int {
    // amount + 1 is larger than any real answer, so it works as "impossible".
    val dp = IntArray(amount + 1) { amount + 1 }
    dp[0] = 0

    for (a in 1..amount) {
        for (c in coins) {
            if (c <= a) dp[a] = minOf(dp[a], dp[a - c] + 1)
        }
    }
    return if (dp[amount] > amount) -1 else dp[amount]
}

fun subsets(nums: IntArray): List<List<Int>> {
    val out = mutableListOf<List<Int>>()
    val path = mutableListOf<Int>()

    fun backtrack(start: Int) {
        out += path.toList()          // every node is a valid subset
        for (i in start until nums.size) {
            path += nums[i]           // choose
            backtrack(i + 1)          // explore
            path.removeAt(path.lastIndex)  // un-choose
        }
    }

    backtrack(0)
    return out
}

fun permute(nums: IntArray): List<List<Int>> {
    val out = mutableListOf<List<Int>>()
    val path = mutableListOf<Int>()
    val used = BooleanArray(nums.size)

    fun backtrack() {
        if (path.size == nums.size) {
            out += path.toList()
            return
        }
        for (i in nums.indices) {
            if (used[i]) continue
            used[i] = true
            path += nums[i]
            backtrack()
            path.removeAt(path.lastIndex)   // undo both parts
            used[i] = false
        }
    }

    backtrack()
    return out
}

fun combinationSum(candidates: IntArray, target: Int): List<List<Int>> {
    val out = mutableListOf<List<Int>>()
    val path = mutableListOf<Int>()

    fun backtrack(start: Int, remaining: Int) {
        if (remaining == 0) {
            out += path.toList()
            return
        }
        for (i in start until candidates.size) {
            val c = candidates[i]
            if (c > remaining) continue
            path += c
            backtrack(i, remaining - c)     // same i — reuse allowed
            path.removeAt(path.lastIndex)
        }
    }

    backtrack(0, target)
    return out
}

fun checkInclusion(s1: String, s2: String): Boolean {
    if (s1.length > s2.length) return false

    val need = IntArray(26)
    val window = IntArray(26)
    for (c in s1) need[c - 'a']++

    for (i in s2.indices) {
        window[s2[i] - 'a']++
        if (i >= s1.length) window[s2[i - s1.length] - 'a']--   // fixed size
        if (need.contentEquals(window)) return true
    }
    return false
}

fun characterReplacement(s: String, k: Int): Int {
    val count = IntArray(26)
    var start = 0
    var maxCount = 0
    var best = 0

    for (end in s.indices) {
        count[s[end] - 'A']++
        maxCount = maxOf(maxCount, count[s[end] - 'A'])

        // Characters needing replacement = window size - most common letter.
        while (end - start + 1 - maxCount > k) {
            count[s[start] - 'A']--
            start++
        }
        best = maxOf(best, end - start + 1)
    }
    return best
}

fun isPalindrome(s: String): Boolean {
    var lo = 0
    var hi = s.length - 1

    while (lo < hi) {
        while (lo < hi && !s[lo].isLetterOrDigit()) lo++
        while (lo < hi && !s[hi].isLetterOrDigit()) hi--
        if (s[lo].lowercaseChar() != s[hi].lowercaseChar()) return false
        lo++
        hi--
    }
    return true
}

fun maxArea(height: IntArray): Int {
    var lo = 0
    var hi = height.size - 1
    var best = 0

    while (lo < hi) {
        best = maxOf(best, minOf(height[lo], height[hi]) * (hi - lo))
        // The shorter line caps this pair — only moving it can improve.
        if (height[lo] < height[hi]) lo++ else hi--
    }
    return best
}

fun middleNode(head: Node?): Node? {
    var slow = head
    var fast = head

    while (fast?.next != null) {
        slow = slow?.next
        fast = fast.next?.next
    }
    return slow
}

fun isHappy(n: Int): Boolean {
    fun squareSum(x: Int): Int {
        var v = x
        var sum = 0
        while (v > 0) {
            val d = v % 10
            sum += d * d
            v /= 10
        }
        return sum
    }

    var slow = n
    var fast = squareSum(n)
    while (fast != 1 && slow != fast) {
        slow = squareSum(slow)
        fast = squareSum(squareSum(fast))
    }
    return fast == 1
}

fun eraseOverlapIntervals(intervals: Array<IntArray>): Int {
    if (intervals.isEmpty()) return 0
    intervals.sortBy { it[1] }        // earliest finish first

    var end = intervals[0][1]
    var kept = 1
    for (i in 1 until intervals.size) {
        if (intervals[i][0] >= end) {
            kept++
            end = intervals[i][1]
        }
    }
    return intervals.size - kept
}

fun intervalIntersection(a: Array<IntArray>, b: Array<IntArray>): List<IntArray> {
    val out = mutableListOf<IntArray>()
    var i = 0
    var j = 0

    while (i < a.size && j < b.size) {
        val lo = maxOf(a[i][0], b[j][0])
        val hi = minOf(a[i][1], b[j][1])
        if (lo <= hi) out += intArrayOf(lo, hi)

        // Whichever ends first can meet nothing later in the other list.
        if (a[i][1] < b[j][1]) i++ else j++
    }
    return out
}

import java.util.PriorityQueue

fun kClosest(points: Array<IntArray>, k: Int): List<IntArray> {
    // Max-heap on squared distance: the root is the worst of the current best k.
    val heap = PriorityQueue<IntArray>(compareByDescending { it[0] * it[0] + it[1] * it[1] })

    for (p in points) {
        heap.add(p)
        if (heap.size > k) heap.poll()
    }
    return heap.toList()
}

fun leastInterval(tasks: CharArray, n: Int): Int {
    val counts = IntArray(26)
    for (t in tasks) counts[t - 'A']++

    val maxCount = counts.max()
    val tiesAtMax = counts.count { it == maxCount }

    // Skeleton built from the most frequent task, plus the tail block.
    val slots = (maxCount - 1) * (n + 1) + tiesAtMax
    return maxOf(tasks.size, slots)   // idles get filled when there is other work
}

fun searchRange(nums: IntArray, target: Int): IntArray {
    fun bound(findFirst: Boolean): Int {
        var lo = 0
        var hi = nums.size - 1
        var found = -1

        while (lo <= hi) {
            val mid = lo + (hi - lo) / 2
            when {
                nums[mid] < target -> lo = mid + 1
                nums[mid] > target -> hi = mid - 1
                else -> {
                    found = mid                       // record, then keep going
                    if (findFirst) hi = mid - 1 else lo = mid + 1
                }
            }
        }
        return found
    }

    return intArrayOf(bound(true), bound(false))
}

fun searchMatrix(matrix: Array<IntArray>, target: Int): Boolean {
    if (matrix.isEmpty() || matrix[0].isEmpty()) return false
    val cols = matrix[0].size

    var lo = 0
    var hi = matrix.size * cols - 1
    while (lo <= hi) {
        val mid = lo + (hi - lo) / 2
        val value = matrix[mid / cols][mid % cols]   // flat index -> cell
        when {
            value == target -> return true
            value < target -> lo = mid + 1
            else -> hi = mid - 1
        }
    }
    return false
}

fun productExceptSelf(nums: IntArray): IntArray {
    val out = IntArray(nums.size)

    var prefix = 1
    for (i in nums.indices) {
        out[i] = prefix          // product of everything before i
        prefix *= nums[i]
    }

    var suffix = 1
    for (i in nums.indices.reversed()) {
        out[i] *= suffix         // fold in everything after i
        suffix *= nums[i]
    }
    return out
}

class NumMatrix(matrix: Array<IntArray>) {
    private val prefix: Array<IntArray>

    init {
        val rows = matrix.size
        val cols = if (rows == 0) 0 else matrix[0].size
        prefix = Array(rows + 1) { IntArray(cols + 1) }   // zero border

        for (r in 0 until rows) {
            for (c in 0 until cols) {
                prefix[r + 1][c + 1] =
                    matrix[r][c] + prefix[r][c + 1] + prefix[r + 1][c] - prefix[r][c]
            }
        }
    }

    fun sumRegion(r1: Int, c1: Int, r2: Int, c2: Int): Int =
        prefix[r2 + 1][c2 + 1] - prefix[r1][c2 + 1] - prefix[r2 + 1][c1] + prefix[r1][c1]
}

fun isAnagram(s: String, t: String): Boolean {
    if (s.length != t.length) return false

    val counts = IntArray(26)
    for (i in s.indices) {
        counts[s[i] - 'a']++
        counts[t[i] - 'a']--
    }
    return counts.all { it == 0 }
}

fun isIsomorphic(s: String, t: String): Boolean {
    if (s.length != t.length) return false

    val forward = HashMap<Char, Char>()
    val claimed = HashSet<Char>()

    for (i in s.indices) {
        val a = s[i]
        val b = t[i]
        val mapped = forward[a]

        if (mapped == null) {
            if (!claimed.add(b)) return false   // b already taken by another char
            forward[a] = b
        } else if (mapped != b) {
            return false
        }
    }
    return true
}

class MinStack {
    private val values = ArrayDeque<Int>()
    private val mins = ArrayDeque<Int>()   // minimum at each depth

    fun push(v: Int) {
        values.addLast(v)
        mins.addLast(if (mins.isEmpty()) v else minOf(v, mins.last()))
    }

    fun pop() {
        values.removeLast()
        mins.removeLast()                  // previous minimum restored
    }

    fun top(): Int = values.last()

    fun getMin(): Int = mins.last()
}

fun evalRPN(tokens: Array<String>): Int {
    val stack = ArrayDeque<Int>()

    for (t in tokens) {
        when (t) {
            "+", "-", "*", "/" -> {
                val b = stack.removeLast()   // right operand pops first
                val a = stack.removeLast()
                stack.addLast(
                    when (t) {
                        "+" -> a + b
                        "-" -> a - b
                        "*" -> a * b
                        else -> a / b        // truncates toward zero
                    },
                )
            }
            else -> stack.addLast(t.toInt())
        }
    }
    return stack.last()
}

class GraphNode(val value: Int) {
    val neighbors = mutableListOf<GraphNode>()
}

fun cloneGraph(node: GraphNode?): GraphNode? {
    val copies = HashMap<GraphNode, GraphNode>()

    fun dfs(cur: GraphNode): GraphNode {
        copies[cur]?.let { return it }

        val copy = GraphNode(cur.value)
        copies[cur] = copy                        // register BEFORE recursing
        for (n in cur.neighbors) copy.neighbors += dfs(n)
        return copy
    }

    return node?.let { dfs(it) }
}

fun canFinish(numCourses: Int, prerequisites: Array<IntArray>): Boolean {
    val adjacency = Array(numCourses) { mutableListOf<Int>() }
    val indegree = IntArray(numCourses)

    for (pair in prerequisites) {
        val course = pair[0]
        val needs = pair[1]
        adjacency[needs] += course     // needs -> course
        indegree[course]++
    }

    val queue = ArrayDeque<Int>()
    for (c in 0 until numCourses) if (indegree[c] == 0) queue.addLast(c)

    var taken = 0
    while (queue.isNotEmpty()) {
        val c = queue.removeFirst()
        taken++
        for (next in adjacency[c]) {
            if (--indegree[next] == 0) queue.addLast(next)
        }
    }
    return taken == numCourses         // shortfall means a cycle
}

fun uniquePaths(m: Int, n: Int): Int {
    val row = IntArray(n) { 1 }        // top row: exactly one path each

    repeat(m - 1) {
        for (c in 1 until n) {
            // row[c] is still the cell above; row[c - 1] is the cell to the left.
            row[c] += row[c - 1]
        }
    }
    return row[n - 1]
}

fun longestCommonSubsequence(a: String, b: String): Int {
    val dp = Array(a.length + 1) { IntArray(b.length + 1) }

    for (i in 1..a.length) {
        for (j in 1..b.length) {
            dp[i][j] = if (a[i - 1] == b[j - 1]) {
                dp[i - 1][j - 1] + 1              // consume both
            } else {
                maxOf(dp[i - 1][j], dp[i][j - 1]) // drop one
            }
        }
    }
    return dp[a.length][b.length]
}

fun letterCombinations(digits: String): List<String> {
    if (digits.isEmpty()) return emptyList()

    val keys = mapOf(
        '2' to "abc", '3' to "def", '4' to "ghi", '5' to "jkl",
        '6' to "mno", '7' to "pqrs", '8' to "tuv", '9' to "wxyz",
    )

    val out = mutableListOf<String>()
    val path = StringBuilder()

    fun backtrack(index: Int) {
        if (index == digits.length) {
            out += path.toString()
            return
        }
        for (c in keys[digits[index]].orEmpty()) {
            path.append(c)
            backtrack(index + 1)
            path.deleteCharAt(path.lastIndex)   // undo
        }
    }

    backtrack(0)
    return out
}

fun exist(board: Array<CharArray>, word: String): Boolean {
    fun search(r: Int, c: Int, index: Int): Boolean {
        if (index == word.length) return true
        if (r !in board.indices || c !in board[0].indices) return false
        if (board[r][c] != word[index]) return false

        val saved = board[r][c]
        board[r][c] = '#'          // mark for this path only
        val found = search(r + 1, c, index + 1) ||
            search(r - 1, c, index + 1) ||
            search(r, c + 1, index + 1) ||
            search(r, c - 1, index + 1)
        board[r][c] = saved        // backtrack

        return found
    }

    for (r in board.indices) {
        for (c in board[0].indices) {
            if (search(r, c, 0)) return true
        }
    }
    return false
}

class Node(val value: Int) { var next: Node? = null }

fun reverseList(head: Node?): Node? {
    var prev: Node? = null
    var cur = head

    while (cur != null) {
        val next = cur.next   // save before destroying the link
        cur.next = prev
        prev = cur
        cur = next
    }
    return prev               // old tail is the new head
}

fun mergeTwoLists(a: Node?, b: Node?): Node? {
    val dummy = Node(0)
    var tail = dummy
    var p = a
    var q = b

    while (p != null && q != null) {
        if (p.value <= q.value) {
            tail.next = p
            p = p.next
        } else {
            tail.next = q
            q = q.next
        }
        tail = tail.next!!
    }
    tail.next = p ?: q      // one list is already sorted and can be attached whole
    return dummy.next
}

fun removeNthFromEnd(head: Node?, n: Int): Node? {
    val dummy = Node(0)
    dummy.next = head

    var fast: Node? = dummy
    var slow: Node? = dummy
    repeat(n + 1) { fast = fast?.next }   // open the gap

    while (fast != null) {
        fast = fast?.next
        slow = slow?.next
    }
    slow?.next = slow?.next?.next          // splice out the target
    return dummy.next
}

fun isPalindrome(head: Node?): Boolean {
    // 1. Middle via fast/slow.
    var slow = head
    var fast = head
    while (fast?.next != null) {
        slow = slow?.next
        fast = fast.next?.next
    }

    // 2. Reverse from the middle onwards.
    var prev: Node? = null
    var cur = slow
    while (cur != null) {
        val next = cur.next
        cur.next = prev
        prev = cur
        cur = next
    }

    // 3. Walk both halves inwards.
    var front = head
    var back = prev
    while (back != null) {
        if (front?.value != back.value) return false
        front = front.next
        back = back.next
    }
    return true
}

fun reorderList(head: Node?) {
    if (head?.next == null) return

    // 1. Split at the middle.
    var slow = head
    var fast = head
    while (fast?.next?.next != null) {
        slow = slow?.next
        fast = fast.next?.next
    }
    var second = slow?.next
    slow?.next = null

    // 2. Reverse the second half.
    var prev: Node? = null
    while (second != null) {
        val next = second.next
        second.next = prev
        prev = second
        second = next
    }

    // 3. Weave the two halves together.
    var first = head
    var back = prev
    while (back != null) {
        val f = first?.next
        val b = back.next
        first?.next = back
        back.next = f
        first = f
        back = b
    }
}

class TreeNode(val value: Int) {
    var left: TreeNode? = null
    var right: TreeNode? = null
}

fun invertTree(root: TreeNode?): TreeNode? {
    if (root == null) return null

    val invertedLeft = invertTree(root.left)   // save before overwriting
    root.left = invertTree(root.right)
    root.right = invertedLeft
    return root
}

fun diameterOfBinaryTree(root: TreeNode?): Int {
    var best = 0

    fun depth(node: TreeNode?): Int {
        if (node == null) return 0
        val l = depth(node.left)
        val r = depth(node.right)
        best = maxOf(best, l + r)   // path turning at this node
        return 1 + maxOf(l, r)
    }

    depth(root)
    return best
}

fun lowestCommonAncestor(root: TreeNode?, p: Int, q: Int): TreeNode? {
    var node = root

    while (node != null) {
        node = when {
            p < node.value && q < node.value -> node.left
            p > node.value && q > node.value -> node.right
            else -> return node       // they split here
        }
    }
    return null
}

fun isValidBST(root: TreeNode?): Boolean {
    fun check(node: TreeNode?, low: Long, high: Long): Boolean {
        if (node == null) return true
        if (node.value <= low || node.value >= high) return false

        // Each descent tightens exactly one side of the range.
        return check(node.left, low, node.value.toLong()) &&
            check(node.right, node.value.toLong(), high)
    }

    return check(root, Long.MIN_VALUE, Long.MAX_VALUE)
}

fun kthSmallest(root: TreeNode?, k: Int): Int {
    val stack = ArrayDeque<TreeNode>()
    var node = root
    var remaining = k

    while (node != null || stack.isNotEmpty()) {
        while (node != null) {          // push the left spine
            stack.addLast(node)
            node = node.left
        }
        val current = stack.removeLast()
        if (--remaining == 0) return current.value   // short-circuit
        node = current.right
    }
    return -1
}

fun findContentChildren(greed: IntArray, cookies: IntArray): Int {
    greed.sort()
    cookies.sort()

    var child = 0
    var cookie = 0
    while (child < greed.size && cookie < cookies.size) {
        if (cookies[cookie] >= greed[child]) child++   // satisfied
        cookie++                                       // spent or discarded
    }
    return child
}

fun canJump(nums: IntArray): Boolean {
    var reach = 0

    for (i in nums.indices) {
        if (i > reach) return false          // gap that cannot be crossed
        reach = maxOf(reach, i + nums[i])
    }
    return true
}

fun partitionLabels(s: String): List<Int> {
    val last = HashMap<Char, Int>()
    for (i in s.indices) last[s[i]] = i     // last occurrence of each letter

    val out = mutableListOf<Int>()
    var start = 0
    var end = 0

    for (i in s.indices) {
        end = maxOf(end, last.getValue(s[i]))
        if (i == end) {                     // nothing inside recurs later
            out += end - start + 1
            start = i + 1
        }
    }
    return out
}

fun canCompleteCircuit(gas: IntArray, cost: IntArray): Int {
    var total = 0
    var tank = 0
    var start = 0

    for (i in gas.indices) {
        val diff = gas[i] - cost[i]
        total += diff
        tank += diff
        if (tank < 0) {      // nothing in [start, i] can be a valid start
            start = i + 1
            tank = 0
        }
    }
    return if (total < 0) -1 else start
}

fun strStr(haystack: String, needle: String): Int {
    if (needle.isEmpty()) return 0
    val lps = IntArray(needle.length)
    var len = 0
    var k = 1
    while (k < needle.length) {
        when {
            needle[k] == needle[len] -> { len++; lps[k] = len; k++ }
            len > 0 -> len = lps[len - 1]
            else -> { lps[k] = 0; k++ }
        }
    }

    var j = 0
    for (i in haystack.indices) {
        while (j > 0 && haystack[i] != needle[j]) j = lps[j - 1]
        if (haystack[i] == needle[j]) j++
        if (j == needle.length) return i - j + 1
    }
    return -1
}

fun repeatedSubstringPattern(s: String): Boolean {
    val n = s.length
    val lps = IntArray(n)
    var len = 0
    var k = 1
    while (k < n) {
        when {
            s[k] == s[len] -> { len++; lps[k] = len; k++ }
            len > 0 -> len = lps[len - 1]
            else -> { lps[k] = 0; k++ }
        }
    }

    val longestBorder = lps[n - 1]
    val period = n - longestBorder
    // Periodic iff the border is non-empty and the period tiles the string exactly.
    return longestBorder > 0 && n % period == 0
}

fun longestPalindrome(s: String): String {
    if (s.isEmpty()) return ""
    val t = buildString {
        append('#')
        for (ch in s) { append(ch); append('#') }
    }

    val p = IntArray(t.length)
    var c = 0
    var r = 0
    for (i in t.indices) {
        if (i < r) p[i] = minOf(r - i, p[2 * c - i])      // reuse the mirror
        while (i - p[i] - 1 >= 0 && i + p[i] + 1 < t.length &&
            t[i - p[i] - 1] == t[i + p[i] + 1]
        ) p[i]++
        if (i + p[i] > r) { c = i; r = i + p[i] }
    }

    val best = p.indices.maxBy { p[it] }
    val start = (best - p[best]) / 2
    return s.substring(start, start + p[best])
}

fun findOrder(n: Int, prerequisites: Array<IntArray>): IntArray {
    val adj = Array(n) { mutableListOf<Int>() }
    val inDegree = IntArray(n)
    for ((course, prereq) in prerequisites.map { it[0] to it[1] }) {
        adj[prereq] += course
        inDegree[course]++
    }

    val ready = ArrayDeque<Int>()
    for (v in 0 until n) if (inDegree[v] == 0) ready += v

    val order = mutableListOf<Int>()
    while (ready.isNotEmpty()) {
        val u = ready.removeFirst()
        order += u
        for (v in adj[u]) if (--inDegree[v] == 0) ready += v
    }

    // Fewer than n emitted means a cycle swallowed the rest.
    return if (order.size == n) order.toIntArray() else IntArray(0)
}

fun criticalConnections(n: Int, connections: List<List<Int>>): List<List<Int>> {
    val adj = Array(n) { mutableListOf<Int>() }
    for (edge in connections) {
        adj[edge[0]] += edge[1]
        adj[edge[1]] += edge[0]
    }

    val disc = IntArray(n) { -1 }
    val low = IntArray(n)
    val bridges = mutableListOf<List<Int>>()
    var timer = 0

    fun dfs(u: Int, parent: Int) {
        disc[u] = timer
        low[u] = timer
        timer++
        for (v in adj[u]) {
            if (v == parent) continue
            if (disc[v] != -1) {
                low[u] = minOf(low[u], disc[v])      // back edge
            } else {
                dfs(v, u)
                low[u] = minOf(low[u], low[v])
                // Strict >: nothing in v's subtree bypasses this edge.
                if (low[v] > disc[u]) bridges += listOf(u, v)
            }
        }
    }

    dfs(0, -1)
    return bridges
}

fun maxMatching(applicants: Int, jobs: Int, edges: List<Pair<Int, Int>>): Int {
    val canDo = Array(applicants) { mutableListOf<Int>() }
    for ((a, j) in edges) canDo[a] += j

    val matchedTo = IntArray(jobs) { -1 }        // job -> applicant, or -1

    fun augment(applicant: Int, seen: BooleanArray): Boolean {
        for (job in canDo[applicant]) {
            if (seen[job]) continue
            seen[job] = true
            // Free job, or its holder can be pushed somewhere else.
            if (matchedTo[job] == -1 || augment(matchedTo[job], seen)) {
                matchedTo[job] = applicant
                return true
            }
        }
        return false
    }

    var total = 0
    for (a in 0 until applicants) {
        if (augment(a, BooleanArray(jobs))) total++
    }
    return total
}

class TreeNode(val value: Int, val left: TreeNode? = null, val right: TreeNode? = null)

fun rob(root: TreeNode?): Int {
    // Returns (best if this node is NOT taken, best if it IS taken).
    fun dfs(node: TreeNode?): Pair<Int, Int> {
        if (node == null) return 0 to 0
        val (leftSkip, leftTake) = dfs(node.left)
        val (rightSkip, rightTake) = dfs(node.right)

        val take = node.value + leftSkip + rightSkip
        val skip = maxOf(leftSkip, leftTake) + maxOf(rightSkip, rightTake)
        return skip to take
    }

    val (skip, take) = dfs(root)
    return maxOf(skip, take)
}

fun shortestTour(cost: Array<IntArray>): Int {
    val n = cost.size
    val full = (1 shl n) - 1
    val inf = Int.MAX_VALUE / 2
    val dp = Array(1 shl n) { IntArray(n) { inf } }
    dp[1][0] = 0                                   // start at city 0

    for (mask in 1..full) {
        if (mask and 1 == 0) continue              // every tour includes city 0
        for (last in 0 until n) {
            val here = dp[mask][last]
            if (here == inf || mask and (1 shl last) == 0) continue
            for (next in 0 until n) {
                if (mask and (1 shl next) != 0) continue
                val nextMask = mask or (1 shl next)
                val candidate = here + cost[last][next]
                if (candidate < dp[nextMask][next]) dp[nextMask][next] = candidate
            }
        }
    }

    return (0 until n).minOf { last -> dp[full][last] + cost[last][0] }
}

data class Metrics(val tp: Int, val fp: Int, val fn: Int, val tn: Int) {
    val accuracy get() = safeDiv(tp + tn, tp + fp + fn + tn)
    val precision get() = safeDiv(tp, tp + fp)
    val recall get() = safeDiv(tp, tp + fn)
    val f1 get() = if (precision + recall == 0.0) 0.0
        else 2 * precision * recall / (precision + recall)

    private fun safeDiv(a: Int, b: Int) = if (b == 0) 0.0 else a.toDouble() / b
}

fun evaluate(scores: DoubleArray, labels: IntArray, threshold: Double): Metrics {
    var tp = 0; var fp = 0; var fn = 0; var tn = 0
    for (i in scores.indices) {
        val predictedPositive = scores[i] >= threshold
        when {
            predictedPositive && labels[i] == 1 -> tp++
            predictedPositive && labels[i] == 0 -> fp++
            !predictedPositive && labels[i] == 1 -> fn++
            else -> tn++
        }
    }
    return Metrics(tp, fp, fn, tn)
}

fun rocAuc(scores: DoubleArray, labels: IntArray): Double {
    val positives = labels.count { it == 1 }
    val negatives = labels.size - positives
    if (positives == 0 || negatives == 0) return 0.5

    val order = scores.indices.sortedBy { scores[it] }
    val rank = DoubleArray(scores.size)

    // Tied scores share the average of the ranks they span.
    var i = 0
    while (i < order.size) {
        var j = i
        while (j + 1 < order.size && scores[order[j + 1]] == scores[order[i]]) j++
        val averageRank = (i + j + 2) / 2.0        // ranks are 1-based
        for (k in i..j) rank[order[k]] = averageRank
        i = j + 1
    }

    val positiveRankSum = scores.indices.filter { labels[it] == 1 }.sumOf { rank[it] }
    return (positiveRankSum - positives * (positives + 1) / 2.0) / (positives.toDouble() * negatives)
}

class Bagging<M>(
    private val rounds: Int,
    private val fit: (List<Int>) -> M,
    private val predict: (M, Int) -> Int,
) {
    private val models = mutableListOf<M>()
    private val bags = mutableListOf<Set<Int>>()

    fun train(n: Int) {
        repeat(rounds) {
            val drawn = List(n) { (0 until n).random() }   // with replacement
            models += fit(drawn)
            bags += drawn.toSet()
        }
    }

    fun vote(row: Int): Int =
        models.map { predict(it, row) }
            .groupingBy { it }.eachCount()
            .maxBy { it.value }.key

    // Only learners that never saw `row` may score it.
    fun outOfBagAccuracy(n: Int, labels: IntArray): Double {
        var scored = 0
        var correct = 0
        for (row in 0 until n) {
            val judges = models.indices.filter { row !in bags[it] }
            if (judges.isEmpty()) continue                 // seen by everyone: no honest vote
            val prediction = judges.map { predict(models[it], row) }
                .groupingBy { it }.eachCount()
                .maxBy { it.value }.key
            scored++
            if (prediction == labels[row]) correct++
        }
        return if (scored == 0) 0.0 else correct.toDouble() / scored
    }
}

fun fitLine(x: DoubleArray, y: DoubleArray, lr: Double, epochs: Int): Pair<Double, Double> {
    var w = 0.0
    var b = 0.0
    val n = x.size

    repeat(epochs) {
        var dw = 0.0
        var db = 0.0
        for (i in 0 until n) {
            val error = (w * x[i] + b) - y[i]
            dw += 2 * error * x[i] / n
            db += 2 * error / n
        }
        // Update only after the full batch is accumulated.
        w -= lr * dw
        b -= lr * db
    }
    return w to b
}

fun classify(train: List<Pair<DoubleArray, Int>>, query: DoubleArray, k: Int): Int {
    fun squaredDistance(a: DoubleArray, b: DoubleArray): Double {
        var sum = 0.0
        for (i in a.indices) {
            val d = a[i] - b[i]
            sum += d * d
        }
        return sum        // no sqrt — ordering is unchanged
    }

    return train
        .sortedBy { squaredDistance(it.first, query) }
        .take(k)
        .groupingBy { it.second }
        .eachCount()
        .maxByOrNull { it.value }!!
        .key
}

fun lloydStep(points: List<DoubleArray>, centroids: List<DoubleArray>): List<DoubleArray> {
    val dim = centroids[0].size
    val sums = Array(centroids.size) { DoubleArray(dim) }
    val counts = IntArray(centroids.size)

    // 1. Assign each point to its nearest centroid.
    for (p in points) {
        var best = 0
        var bestDistance = Double.MAX_VALUE
        for (c in centroids.indices) {
            var d = 0.0
            for (i in 0 until dim) {
                val diff = p[i] - centroids[c][i]
                d += diff * diff
            }
            if (d < bestDistance) {
                bestDistance = d
                best = c
            }
        }
        counts[best]++
        for (i in 0 until dim) sums[best][i] += p[i]
    }

    // 2. Move each centroid to the mean of what it captured.
    return centroids.mapIndexed { c, old ->
        if (counts[c] == 0) old else DoubleArray(dim) { i -> sums[c][i] / counts[c] }
    }
}

data class Metrics(val precision: Double, val recall: Double, val f1: Double)

fun evaluate(actual: IntArray, predicted: IntArray): Metrics {
    var tp = 0
    var fp = 0
    var fn = 0

    for (i in actual.indices) {
        when {
            predicted[i] == 1 && actual[i] == 1 -> tp++
            predicted[i] == 1 && actual[i] == 0 -> fp++
            predicted[i] == 0 && actual[i] == 1 -> fn++
        }
    }

    val precision = if (tp + fp == 0) 0.0 else tp.toDouble() / (tp + fp)
    val recall = if (tp + fn == 0) 0.0 else tp.toDouble() / (tp + fn)
    val f1 = if (precision + recall == 0.0) 0.0 else 2 * precision * recall / (precision + recall)
    return Metrics(precision, recall, f1)
}

fun softmax(logits: DoubleArray): DoubleArray {
    val max = logits.max()                    // shift for stability
    val exps = DoubleArray(logits.size) { Math.exp(logits[it] - max) }
    val sum = exps.sum()
    return DoubleArray(exps.size) { exps[it] / sum }
}

fun crossEntropy(logits: DoubleArray, label: Int): Double {
    val p = softmax(logits)
    return -Math.log(p[label].coerceAtLeast(1e-12))   // guard log(0)
}

// gradW = gradOut ⊗ input ;  gradInput = Wᵀ · gradOut
fun denseBackward(
    input: DoubleArray,
    weights: Array<DoubleArray>,
    gradOut: DoubleArray,
): Pair<Array<DoubleArray>, DoubleArray> {
    val gradW = Array(weights.size) { j ->
        DoubleArray(input.size) { i -> gradOut[j] * input[i] }
    }

    val gradInput = DoubleArray(input.size) { i ->
        var sum = 0.0
        for (j in weights.indices) sum += weights[j][i] * gradOut[j]
        sum
    }

    return gradW to gradInput
}

class SgdMomentum(private val lr: Double, private val beta: Double = 0.9) {
    private var velocity: DoubleArray? = null

    fun step(params: DoubleArray, grads: DoubleArray) {
        val v = velocity ?: DoubleArray(params.size).also { velocity = it }

        for (i in params.indices) {
            v[i] = beta * v[i] + (1 - beta) * grads[i]   // decaying average
            params[i] -= lr * v[i]
        }
    }
}

fun bagOfWords(docs: List<String>): Pair<List<String>, List<IntArray>> {
    val vocab = docs
        .flatMap { it.lowercase().split(" ") }
        .filter { it.isNotBlank() }
        .distinct()
        .sorted()                                   // stable column order
    val column = vocab.withIndex().associate { (i, w) -> w to i }

    val vectors = docs.map { doc ->
        val v = IntArray(vocab.size)
        for (w in doc.lowercase().split(" ")) column[w]?.let { v[it]++ }
        v
    }
    return vocab to vectors
}

fun tfidf(docs: List<List<String>>): List<Map<String, Double>> {
    val n = docs.size

    // Document frequency: how many docs contain each term at least once.
    val df = HashMap<String, Int>()
    for (doc in docs) {
        for (term in doc.toSet()) df[term] = (df[term] ?: 0) + 1
    }

    return docs.map { doc ->
        val counts = doc.groupingBy { it }.eachCount()
        counts.mapValues { (term, count) ->
            val tf = count.toDouble() / doc.size
            val idf = Math.log(n.toDouble() / (1 + (df[term] ?: 0))) + 1.0
            tf * idf
        }
    }
}

fun mostFrequentPair(corpus: List<List<String>>): Pair<String, String>? {
    val counts = HashMap<Pair<String, String>, Int>()
    for (word in corpus) {
        for (i in 0 until word.size - 1) {
            val pair = word[i] to word[i + 1]
            counts[pair] = (counts[pair] ?: 0) + 1
        }
    }
    return counts.maxByOrNull { it.value }?.key
}

fun applyMerge(corpus: List<List<String>>, pair: Pair<String, String>): List<List<String>> =
    corpus.map { word ->
        val out = mutableListOf<String>()
        var i = 0
        while (i < word.size) {
            if (i < word.size - 1 && word[i] == pair.first && word[i + 1] == pair.second) {
                out += pair.first + pair.second
                i += 2                      // the pair is consumed
            } else {
                out += word[i]
                i++
            }
        }
        out
    }

fun attention(
    query: DoubleArray,
    keys: Array<DoubleArray>,
    values: Array<DoubleArray>,
): DoubleArray {
    val d = query.size

    val scores = DoubleArray(keys.size) { k ->
        var dot = 0.0
        for (i in 0 until d) dot += query[i] * keys[k][i]
        dot / Math.sqrt(d.toDouble())        // scale before softmax
    }

    val weights = softmax(scores)

    val out = DoubleArray(values[0].size)
    for (k in values.indices) {
        for (i in out.indices) out[i] += weights[k] * values[k][i]
    }
    return out
}

import kotlin.random.Random

fun selectAction(q: DoubleArray, epsilon: Double, random: Random): Int =
    if (random.nextDouble() < epsilon) {
        random.nextInt(q.size)                     // explore
    } else {
        q.indices.maxByOrNull { q[it] }!!          // exploit
    }

fun discountedReturns(rewards: DoubleArray, gamma: Double): DoubleArray {
    val out = DoubleArray(rewards.size)
    var running = 0.0

    // G_t = r_t + gamma * G_{t+1}, so build it back to front.
    for (t in rewards.indices.reversed()) {
        running = rewards[t] + gamma * running
        out[t] = running
    }
    return out
}

import kotlin.random.Random

data class Transition(
    val state: Int,
    val action: Int,
    val reward: Double,
    val nextState: Int,
    val done: Boolean,
)

class ReplayBuffer(private val capacity: Int) {
    private val storage = ArrayList<Transition>(capacity)
    private var cursor = 0

    fun add(t: Transition) {
        if (storage.size < capacity) storage += t else storage[cursor] = t
        cursor = (cursor + 1) % capacity     // ring, so add stays O(1)
    }

    fun sample(batch: Int, random: Random): List<Transition> =
        List(batch) { storage[random.nextInt(storage.size)] }

    val size: Int get() = storage.size
}
